class Solution {
    private String[] words;
    private int[] score,available;
    public int maxScoreWords(String[] words,char[] letters,int[] score){
        this.words=words;
        this.score=score;
        available=new int[26];
        for(char ch:letters)available[ch-'a']++;
        return dfs(0);
    }
    private int dfs(int index){
        if(index==words.length)return 0;
        int best=dfs(index+1);
        int[] need=new int[26];
        int wordScore=0;
        boolean valid=true;
        for(char ch:words[index].toCharArray()){
            int letter=ch-'a';
            wordScore+=score[letter];
            if(++need[letter]>available[letter])valid=false;
        }
        if(valid){
            for(int i=0;i<26;i++)available[i]-=need[i];
            best=Math.max(best,wordScore+dfs(index+1));
            for(int i=0;i<26;i++)available[i]+=need[i];
        }
        return best;
    }
}

